iff --git a/pkg/kubelet/util/boottime_util_linux.go b/pkg/kubelet/util/boottime_util_linux.go
index b48ef392eeb..02776846326 100644
--- a/pkg/kubelet/util/boottime_util_linux.go
+++ b/pkg/kubelet/util/boottime_util_linux.go
@@ -26,12 +26,19 @@ import (
        "golang.org/x/sys/unix"
 )
 
+var bootTime time.Time
+
 // GetBootTime returns the time at which the machine was started, truncated to the nearest second
 func GetBootTime() (time.Time, error) {
-       currentTime := time.Now()
-       var info unix.Sysinfo_t
-       if err := unix.Sysinfo(&info); err != nil {
-               return time.Time{}, fmt.Errorf("error getting system uptime: %s", err)
+       // cache the boottime value to avoid skew problems
+       // Ref: https://issues.k8s.io/127841
+       if bootTime.IsZero() {
+               currentTime := time.Now()
+               var info unix.Sysinfo_t
+               if err := unix.Sysinfo(&info); err != nil {
+                       return time.Time{}, fmt.Errorf("error getting system uptime: %s", err)
+               }
+               bootTime = currentTime.Add(-time.Duration(info.Uptime) * time.Second).Truncate(time.Second)
        }
-       return currentTime.Add(-time.Duration(info.Uptime) * time.Second).Truncate(time.Second), nil
+
+       return bootTime, nil
 }
